func parseContentLineForProfile(line string) (ip string, hosts []string, ok bool) {
	trimmed := strings.TrimSpace(line)
	if trimmed == "" {
		return "", nil, false
	}
	var rest string
	if strings.HasPrefix(trimmed, "#") {
		// strip leading # and trim
		rest = strings.TrimSpace(trimmed[1:])
		if rest == "" {
			return "", nil, false
		}
	} else {
		rest = trimmed
	}
	// strip inline comment: split on # and take first part
	if idx := strings.Index(rest, "#"); idx >= 0 {
		rest = strings.TrimSpace(rest[:idx])
		if rest == "" {
			return "", nil, false
		}
	}
	fields := strings.Fields(rest)
	if len(fields) < 2 {
		return "", nil, false
	}
	ipStr := fields[0]
	if !isValidIP(ipStr) {
		return "", nil, false
	}
	hosts = fields[1:]
	return ipStr, hosts, true
}

