func (hf *HostsFile) getAllEntries() []Entry {
	var all []Entry
	// default entries in order of DefaultLines? Or DefaultEntries order? They are same order. Use DefaultLines order for default part? But for list, default entries should appear in file order, then profiles in file order, each profile's entries in file order.
	// For default, iterate DefaultLines and collect entries in order.
	for _, dl := range hf.DefaultLines {
		if dl.Kind == "entry" {
			all = append(all, dl.Entry)
		}
	}
	for _, p := range hf.Profiles {
		for _, e := range p.Entries {
			all = append(all, e)
		}
	}
	return all
}

func (hf *HostsFile) getStatusEntries() []Entry {
	var out []Entry
	for _, p := range hf.Profiles {
		out = append(out, Entry{Profile: p.Name, Status: p.Status})
	}
	return out
}

func serializeHostsFile(hf *HostsFile) string {
	var b strings.Builder
	// default lines
	for _, dl := range hf.DefaultLines {
		if dl.Kind == "blank" {
			b.WriteString("\n")
		} else if dl.Kind == "comment" {
			b.WriteString(dl.Raw + "\n")
