// Hosts handling
type Entry struct {
	Profile string
	Status  string // "on" or "off"
	IP      string
	Host    string // domain
}

type ProfileData struct {
	Name    string
	Status  string // on/off
	Entries []Entry // IP/Host pairs (IP and Host)
	Order   int
}

type HostsFile struct {
	DefaultEntries []Entry // for default, each with Profile=default, Status on/off, IP, Host
	DefaultComments []string // actually need ordered preservation of default zone lines
	// To preserve order and comments, we store default lines as slice of DefaultLine
	DefaultLines []DefaultLine
	Profiles []*ProfileData // in file order
	ProfileMap map[string]*ProfileData
	HasHeader bool
}

type DefaultLine struct {
	Kind string // "blank", "comment", "entry"
	Raw  string // for comment? normalized?
	Entry Entry // for entry
	Comment string // for comment line normalized?
}

func isValidIP(s string) bool {
	return net.ParseIP(s) != nil
}

func extractProfileName(rest string) (string, bool) {
	// rest is already trimmed
	// match allowed chars: a-z,0-9,-,_,.,space
	// iterate
	i := 0
	for _, r := range rest {
		if (r >= 'a' && r <= 'z') || (r >= '0' && r <= '9') || r == '-' || r == '_' || r == '.' || r == ' ' {
			i += len(string(r))
		} else {
			break
		}
	}
	matched := rest[:i]
	matched = strings.TrimSpace(matched)
	if matched == "" {
		return "", false
	}
	return matched, true
}

func parseHeaderLine(line string) (name string, status string, isHeader bool) {
	trimmed := strings.TrimSpace(line)
	if !strings.HasPrefix(trimmed, "# profile") {
		return "", "", false
	}
	// check off/on first
