		// However need to handle "# profile.off" without name => rest "" => no profile => not header.
		rest = trimmed[len("# profile.off"):]
		st = "off"
	} else if strings.HasPrefix(trimmed, "# profile.on") {
		rest = trimmed[len("# profile.on"):]
		st = "on"
	} else if strings.HasPrefix(trimmed, "# profile") {
		rest = trimmed[len("# profile"):]
		st = "on"
	} else {
		return "", "", false
	}
	// rest may start with space/tab or directly name? For "# profile.onmyprof" (no space), rest is "myprof", TrimSpace gives "myprof", which would be profile. Is that intended? Possibly. But our earlier test "#profile.on myprof" (no space after #) was not recognized because it doesn't start with "# profile" (missing space). For "# profile.onmyprof", it does start with "# profile.on", rest "myprof", would be recognized. Is that correct per original? Unknown. We'll allow it.
	rest = strings.TrimSpace(rest)
