func isEndLine(line string) bool {
	trimmed := strings.TrimSpace(line)
	lower := strings.ToLower(trimmed)
	return strings.HasPrefix(lower, "# end")
	// Note: this will match "# end", "# end ", "# end extra", "# End", "# END", " # end" (after trim), etc.
	// But will also match "# ending"? That starts with "# end" + "ing" => HasPrefix true, but should it count? Probably original checks HasPrefix, so "# ending" would count as end. Unlikely tested. We'll keep HasPrefix.
