	beforeHash := rest
	if idx := strings.Index(rest, "#"); idx >= 0 {
		beforeHash = strings.TrimSpace(rest[:idx])
		// Note: for commented lines, the first # already stripped, second # is inline. For uncommented, first # is inline.
		// If rest is "10.0.0.1 dis1 # comment", beforeHash "10.0.0.1 dis1"
		// If rest is "comment line", beforeHash "comment line" (no #, same)
