func parseFromFile(content string) []Entry {
	// Parse each line as profile content (all hostnames, strip #, validate IP)
	var out []Entry
	lines := strings.Split(content, "\n")
	for _, line := range lines {
		ip, hosts, ok := parseContentLineForProfile(line)
		if !ok {
			continue
		}
		for _, h := range hosts {
			out = append(out, Entry{IP: ip, Host: h})
		}
	}
	return out
